<template>
  <div @click="closeStoragePicker" @keydown.esc="closeStoragePicker">
    <div class="page-header"><div><h1 class="page-title">存储卷</h1><p class="page-subtitle">在环境命名空间中管理应用持久化数据</p></div><button class="btn btn-primary" :disabled="!environmentID" @click="openCreate">+ 创建存储卷</button></div>
    <div v-if="error" class="k8s-banner k8s-banner-warn section-gap">{{ error }}</div>
    <section class="storage-context" @click.stop><div class="storage-picker"><span class="context-picker-label">项目</span><button data-testid="storage-project-trigger" type="button" class="context-picker-trigger" :class="{ 'is-open': activeStoragePicker === 'project' }" :aria-expanded="activeStoragePicker === 'project'" aria-haspopup="listbox" @click="toggleStoragePicker('project')"><span class="context-picker-value">{{ selectedProject?.name || '选择项目' }}</span><ChevronDown :size="15" /></button><div v-if="activeStoragePicker === 'project'" data-testid="storage-project-menu" class="context-picker-menu" role="listbox" aria-label="项目"><button v-for="project in projects" :key="project.id" type="button" class="context-picker-option" :class="{ 'is-selected': project.id === projectID }" role="option" :aria-selected="project.id === projectID" @click="selectProject(project.id)"><span><strong>{{ project.name }}</strong><small>{{ project.description || '未设置项目说明' }}</small></span><Check v-if="project.id === projectID" :size="15" /></button><div v-if="!projects.length" class="context-picker-empty">暂无项目</div></div></div><div class="storage-picker"><span class="context-picker-label">环境</span><button data-testid="storage-environment-trigger" type="button" class="context-picker-trigger" :class="{ 'is-open': activeStoragePicker === 'environment' }" :aria-expanded="activeStoragePicker === 'environment'" aria-haspopup="listbox" :disabled="!selectedProject" @click="toggleStoragePicker('environment')"><span class="context-picker-value">{{ selectedEnvironment ? `${selectedEnvironment.name} · ${selectedEnvironment.namespace}` : '选择环境' }}</span><ChevronDown :size="15" /></button><div v-if="activeStoragePicker === 'environment'" data-testid="storage-environment-menu" class="context-picker-menu context-picker-menu--environment" role="listbox" aria-label="环境"><button v-for="environment in selectedProject?.environments || []" :key="environment.id" type="button" class="context-picker-option" :class="{ 'is-selected': environment.id === environmentID }" role="option" :aria-selected="environment.id === environmentID" @click="selectEnvironment(environment.id)"><span><strong>{{ environment.name }}</strong><small>{{ environment.namespace }}</small></span><Check v-if="environment.id === environmentID" :size="15" /></button><div v-if="!(selectedProject?.environments || []).length" class="context-picker-empty">该项目暂无环境</div></div></div></section>
    <div v-if="environmentID && loaded && !claims.length" class="empty-state"><span class="empty-icon">▣</span><span class="empty-text">当前环境还没有平台托管存储卷</span></div>
    <div v-else-if="claims.length" class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>存储卷</th><th>容量</th><th>StorageClass</th><th>状态</th><th>绑定节点</th><th>数据回收</th><th>引用</th><th>操作</th></tr></thead><tbody><tr v-for="claim in claims" :key="claim.name"><td class="cell-primary">{{ claim.name }}<small v-if="migrationFor(claim)?.target_pvc_name" class="node-meta">迁移目标：{{ migrationFor(claim).target_pvc_name }}</small></td><td>{{ claim.storage || '-' }}</td><td>{{ claim.storage_class_name || '默认 StorageClass' }}</td><td><span class="badge" :class="claim.phase === 'Bound' ? 'badge-online' : 'badge-deploying'">{{ claim.phase || 'Pending' }}</span><small v-if="migrationFor(claim)" class="migration-status">{{ migrationLabel(migrationFor(claim).status) }}</small></td><td><span v-if="claim.bound_node_display_name">{{ claim.bound_node_display_name }}<small class="node-meta">{{ claim.bound_node }}</small></span><span v-else-if="claim.wait_for_first_consumer">首次挂载时决定</span><span v-else>-</span></td><td><span class="badge" :class="claim.reclaim_policy === 'Delete' ? 'badge-danger' : 'badge-offline'">{{ claim.reclaim_policy || '-' }}</span></td><td>{{ claim.references?.join('、') || '-' }}</td><td><div class="btn-group"><button v-if="claim.is_local && claim.bound_node && !migrationFor(claim)" class="btn btn-sm" @click="openMigration(claim)">迁移</button><button v-if="claim.is_local && claim.bound_node && !migrationFor(claim)" data-testid="open-directory-import" class="btn btn-sm" @click="openImport(claim)">导入目录</button><button v-if="claim.is_local && claim.bound_node" class="btn btn-sm" @click="openBackup(claim)">备份</button><button v-if="migrationFor(claim)?.status === 'cleanup_pending'" class="btn btn-sm btn-danger" @click="requestCleanup(migrationFor(claim))">清理源卷</button><button class="icon-button danger-action" title="删除存储卷" :disabled="claim.references?.length || !!migrationFor(claim)" @click="requestDelete(claim)"><Trash2 :size="16" /></button></div></td></tr></tbody></table></div></div>

    <div v-if="showCreate" class="overlay" @click.self="showCreate = false"><div class="modal"><h2 class="modal-title">创建存储卷</h2><form @submit.prevent="createClaim"><div class="form-group"><label class="form-label">名称</label><input v-model.trim="form.name" class="form-input" required pattern="[a-z0-9]([-a-z0-9]*[a-z0-9])?" placeholder="karakeep-data" /></div><div class="form-group"><label class="form-label">容量</label><div class="quantity-input"><input v-model.number="form.storage_value" data-testid="storage-capacity-value" type="number" min="1" step="1" class="form-input" required placeholder="5" /><select v-model="form.storage_unit" data-testid="storage-capacity-unit" class="form-select"><option value="Mi">Mi</option><option value="Gi">Gi</option><option value="Ti">Ti</option></select></div><p class="form-hint">首期仅支持 ReadWriteOnce，挂载该卷的应用只能运行一个副本。</p></div><div class="form-group"><label class="form-label">StorageClass</label><select v-model="form.storage_class_name" class="form-select"><option value="">使用默认 StorageClass</option><option v-for="item in storageClasses" :key="item.name" :value="item.name">{{ item.name }}{{ item.is_default ? '（默认）' : '' }} · {{ item.volume_binding_mode || 'Immediate' }}</option></select></div><div class="modal-actions"><button type="button" class="btn" @click="showCreate = false">取消</button><button class="btn btn-primary" :disabled="saving || !validStorage">{{ saving ? '创建中...' : '创建存储卷' }}</button></div></form></div></div>
    <div v-if="deleteTarget" class="overlay" @click.self="deleteTarget = null"><div class="modal"><h2 class="modal-title">删除存储卷</h2><p class="confirm-copy">将删除 PVC“{{ deleteTarget.name }}”。{{ deleteTarget.reclaim_policy === 'Delete' ? '该 PV 的回收策略为 Delete，底层数据可能一并被清除。' : '底层数据的保留行为由 PV 回收策略决定。' }}</p><div class="modal-actions"><button class="btn" @click="deleteTarget = null">取消</button><button class="btn btn-danger" :disabled="saving" @click="deleteClaim">确认删除</button></div></div></div>
    <div v-if="migrationTarget" class="overlay" @click.self="migrationTarget = null"><div class="modal"><h2 class="modal-title">迁移本地存储卷</h2><p class="confirm-copy">应用会在复制数据时短暂停止。目标工作负载就绪后，源卷将保留，待确认后再清理。</p><div class="form-group"><label class="form-label">目标节点</label><select v-model="migrationNode" class="form-select" required><option value="" disabled>选择不同于当前绑定节点的服务器</option><option v-for="node in migrationNodes" :key="node.name" :value="node.name">{{ node.display_name || node.name }} · {{ node.name }}</option></select></div><div class="modal-actions"><button class="btn" @click="migrationTarget = null">取消</button><button class="btn btn-primary" :disabled="saving || !migrationNode" @click="createMigration">开始迁移</button></div></div></div>
    <div v-if="cleanupTarget" class="overlay" @click.self="cleanupTarget = null"><div class="modal"><h2 class="modal-title">清理源存储卷</h2><p class="confirm-copy">目标工作负载已就绪。删除源 PVC 后，{{ cleanupTarget.source_pvc_name }} 的底层数据将按其 PV 回收策略处理，此操作不可恢复。</p><div class="modal-actions"><button class="btn" @click="cleanupTarget = null">取消</button><button class="btn btn-danger" :disabled="saving" @click="cleanupMigration">确认清理</button></div></div></div>
    <div v-if="backupTarget" class="overlay" @click.self="backupTarget = null"><div class="modal"><h2 class="modal-title">备份 {{ backupTarget.name }}</h2><p class="confirm-copy">备份会从绑定节点复制本地卷数据到指定服务器目录。</p><form @submit.prevent="createBackup"><div class="form-group"><label class="form-label">备份服务器</label><select v-model.number="backupForm.backup_server_id" class="form-select" required><option :value="0" disabled>选择服务器</option><option v-for="server in backupServers" :key="server.id" :value="server.id">{{ server.name }} · {{ server.host }}</option></select></div><div class="form-group"><label class="form-label">备份根目录</label><input v-model.trim="backupForm.backup_root" class="form-input" placeholder="/data/cylism-backups" required /></div><div v-if="backups.length" class="backup-list"><div v-for="backup in backups" :key="backup.id" class="backup-row"><span>{{ backup.backup_path }}</span><small>{{ backup.status }} · {{ backup.bytes || 0 }} bytes<span v-if="backup.restore_status"> · 恢复{{ backup.restore_status }}</span></small><button v-if="backup.status === 'succeeded' && backup.restore_status !== 'running'" type="button" class="btn btn-sm btn-danger" @click="restoreBackup(backup)">恢复</button></div></div><div class="modal-actions"><button type="button" class="btn" @click="backupTarget = null">关闭</button><button class="btn btn-primary" :disabled="saving">{{ saving ? '处理中...' : '开始备份' }}</button></div></form></div></div>
    <div v-if="importTarget" class="overlay" @click.self="importTarget = null"><div class="modal modal-wide"><h2 class="modal-title">导入宿主机目录到 {{ importTarget.name }}</h2><p class="confirm-copy">平台会停止引用该卷的应用，创建本地归档后复制并校验数据。源目录和 PVC 可位于不同节点；完成校验并恢复应用后，归档才可删除。</p><form class="import-form" @submit.prevent="createImport"><div class="form-group"><label class="form-label">源服务器</label><select v-model.number="importForm.source_server_id" data-testid="import-source-server" class="form-select" required><option :value="0" disabled>选择已登记的 SSH 服务器</option><option v-for="server in backupServers" :key="server.id" :value="server.id">{{ server.name }} · {{ server.host }}</option></select></div><div class="form-group"><label class="form-label">源目录</label><input v-model.trim="importForm.source_path" data-testid="import-source-path" class="form-input" required placeholder="/data/legacy/karakeep" /><p class="form-hint">不允许系统目录。归档由平台保存在源服务器或 PVC 节点的 /data/cylism-import-backups。</p></div><label class="check-row"><input v-model="importForm.confirm_data_replace" data-testid="import-confirm-replace" type="checkbox" />我确认若目标 PVC 已有数据，可先备份并覆盖</label><div v-if="imports.length" class="import-list"><div v-for="task in imports" :key="task.id" class="import-row"><div><strong>{{ importLabel(task.status) }}</strong><span>{{ task.source_path }} → {{ task.target_path }}</span><small v-if="task.detail">{{ task.detail }}</small><small v-if="task.source_checksum && task.target_checksum">校验摘要：{{ task.target_checksum.slice(0, 12) }}...</small></div><button v-if="task.status === 'succeeded' && task.verified_at && !task.backup_deleted_at" type="button" class="btn btn-sm btn-danger" @click="deleteImportBackup(task)">删除备份</button><small v-else-if="task.backup_deleted_at">备份已删除</small></div></div><div class="modal-actions"><button type="button" class="btn" @click="importTarget = null">关闭</button><button class="btn btn-primary" :disabled="saving || !importForm.source_server_id || !importForm.source_path">{{ saving ? '处理中...' : '开始导入' }}</button></div></form></div></div>
  </div>
</template>

<script setup>
import { computed, onUnmounted, ref, watch } from 'vue'
import { Check, ChevronDown, Trash2 } from 'lucide-vue-next'
import { api } from '../api/index.js'

const projects = ref([])
const claims = ref([])
const storageClasses = ref([])
const migrations = ref([])
const nodes = ref([])
const backupServers = ref([])
const backups = ref([])
const imports = ref([])
const projectID = ref(0)
const environmentID = ref(0)
const loaded = ref(false)
const error = ref('')
const saving = ref(false)
const showCreate = ref(false)
const deleteTarget = ref(null)
const migrationTarget = ref(null)
const migrationNode = ref('')
const cleanupTarget = ref(null)
const backupTarget = ref(null)
const backupForm = ref({ backup_server_id: 0, backup_root: '/data/cylism-backups' })
const importTarget = ref(null)
const importForm = ref({ source_server_id: 0, source_path: '', confirm_data_replace: false })
const form = ref(newClaimForm())
const activeStoragePicker = ref('')
let migrationPollTimer
let backupPollTimer
let importPollTimer
const selectedProject = computed(() => projects.value.find(project => project.id === projectID.value) || null)
const selectedEnvironment = computed(() => selectedProject.value?.environments?.find(environment => environment.id === environmentID.value) || null)
const validStorage = computed(() => Number.isInteger(form.value.storage_value) && form.value.storage_value > 0 && ['Mi', 'Gi', 'Ti'].includes(form.value.storage_unit))
const migrationNodes = computed(() => nodes.value.filter(node => node.name && node.name !== migrationTarget.value?.bound_node && (node.status === 'Ready' || node.status === 'ready')))

function newClaimForm() { return { name: '', storage_value: 5, storage_unit: 'Gi', storage_class_name: '' } }
function closeStoragePicker() { activeStoragePicker.value = '' }
function toggleStoragePicker(picker) { activeStoragePicker.value = activeStoragePicker.value === picker ? '' : picker }
function selectProject(value) { closeStoragePicker(); projectID.value = Number(value) || 0 }
function selectEnvironment(value) { closeStoragePicker(); environmentID.value = Number(value) || 0 }
async function loadProjects() { try { projects.value = await api.get('/projects') || [] } catch (e) { error.value = e.message || '加载项目失败' } }
async function loadClaims() { if (!environmentID.value) { claims.value = []; migrations.value = []; loaded.value = false; stopMigrationPolling(); return }; loaded.value = false; error.value = ''; try { const [items, classes, tasks, clusterNodes, servers] = await Promise.all([api.get(`/k8s/persistent-volume-claims?environment_id=${environmentID.value}`), api.get('/k8s/storage-classes'), api.get(`/k8s/persistent-volume-migrations?environment_id=${environmentID.value}`), api.get('/nodes'), api.get('/servers')]); claims.value = items || []; storageClasses.value = classes || []; migrations.value = tasks || []; nodes.value = clusterNodes || []; backupServers.value = servers || []; loaded.value = true; syncMigrationPolling() } catch (e) { error.value = e.message || '加载存储卷失败' } }
function openCreate() { form.value = newClaimForm(); showCreate.value = true }
async function createClaim() { if (!validStorage.value) return; saving.value = true; error.value = ''; try { const { storage_value, storage_unit, ...claim } = form.value; await api.post('/k8s/persistent-volume-claims', { environment_id: environmentID.value, ...claim, storage: `${storage_value}${storage_unit}` }); showCreate.value = false; await loadClaims() } catch (e) { error.value = e.message || '创建存储卷失败' } finally { saving.value = false } }
function requestDelete(claim) { deleteTarget.value = claim }
function migrationFor(claim) { return migrations.value.find(item => item.source_pvc_name === claim.name && item.status !== 'cleaned') || null }
function migrationLabel(status) { return ({ pending: '等待预检', preflight: '预检中', provisioning_target: '预配目标卷', stopping_source: '停止源工作负载', copying: '复制数据中', cutover: '切换中', waiting_ready: '等待就绪', cleanup_pending: '等待清理源卷', failed: '迁移失败', rolled_back: '已回滚' })[status] || status }
function migrationRunning(task) { return !['cleanup_pending', 'failed', 'rolled_back', 'cleaned'].includes(task.status) }
function syncMigrationPolling() { if (migrations.value.some(migrationRunning) && !migrationPollTimer) migrationPollTimer = window.setInterval(loadClaims, 2500); if (!migrations.value.some(migrationRunning)) stopMigrationPolling() }
function stopMigrationPolling() { if (migrationPollTimer) window.clearInterval(migrationPollTimer); migrationPollTimer = undefined }
function openMigration(claim) { migrationTarget.value = claim; migrationNode.value = '' }
async function createMigration() { if (!migrationTarget.value || !migrationNode.value) return; saving.value = true; error.value = ''; try { await api.post(`/k8s/persistent-volume-claims/${migrationTarget.value.name}/migrations`, { environment_id: environmentID.value, target_node_name: migrationNode.value }); migrationTarget.value = null; await loadClaims() } catch (e) { error.value = e.message || '创建存储卷迁移失败' } finally { saving.value = false } }
function requestCleanup(migration) { cleanupTarget.value = migration }
async function cleanupMigration() { if (!cleanupTarget.value) return; saving.value = true; error.value = ''; try { await api.post(`/k8s/persistent-volume-migrations/${cleanupTarget.value.id}/cleanup`); cleanupTarget.value = null; await loadClaims() } catch (e) { error.value = e.message || '清理源存储卷失败' } finally { saving.value = false } }
function backupRunning(backup) { return ['accepted', 'running'].includes(backup.status) || backup.restore_status === 'running' }
function syncBackupPolling() { if (backupTarget.value && backups.value.some(backupRunning) && !backupPollTimer) backupPollTimer = window.setInterval(refreshBackups, 2500); if (!backupTarget.value || !backups.value.some(backupRunning)) stopBackupPolling() }
function stopBackupPolling() { if (backupPollTimer) window.clearInterval(backupPollTimer); backupPollTimer = undefined }
async function refreshBackups() { if (!backupTarget.value) return; try { backups.value = await api.get(`/k8s/persistent-volume-claims/${backupTarget.value.name}/backups?environment_id=${environmentID.value}`) || []; syncBackupPolling() } catch (e) { error.value = e.message || '读取备份记录失败'; stopBackupPolling() } }
async function openBackup(claim) { backupTarget.value = claim; backupForm.value = { backup_server_id: backupServers.value[0]?.id || 0, backup_root: '/data/cylism-backups' }; await refreshBackups() }
async function createBackup() { if (!backupTarget.value) return; saving.value = true; error.value = ''; try { await api.post(`/k8s/persistent-volume-claims/${backupTarget.value.name}/backups`, { environment_id: environmentID.value, ...backupForm.value }); await refreshBackups() } catch (e) { error.value = e.message || '创建备份失败' } finally { saving.value = false } }
async function restoreBackup(backup) { if (!backupTarget.value || !window.confirm('恢复会覆盖当前 PVC 数据，并短暂停止引用它的工作负载，确定继续吗？')) return; saving.value = true; error.value = ''; try { await api.post(`/k8s/persistent-volume-claims/${backupTarget.value.name}/backups/${backup.id}/restore`, { environment_id: environmentID.value, confirm_data_replace: true }); await refreshBackups() } catch (e) { error.value = e.message || '恢复备份失败' } finally { saving.value = false } }
function importRunning(task) { return !['succeeded', 'failed'].includes(task.status) }
function importLabel(status) { return ({ pending: '等待执行', preflight: '预检中', stopping_workload: '停止应用中', backing_up: '创建备份中', copying: '复制数据中', verifying: '校验中', restoring_workload: '恢复应用中', succeeded: '导入完成', failed: '导入失败' })[status] || status }
function syncImportPolling() { if (importTarget.value && imports.value.some(importRunning) && !importPollTimer) importPollTimer = window.setInterval(refreshImports, 2500); if (!importTarget.value || !imports.value.some(importRunning)) stopImportPolling() }
function stopImportPolling() { if (importPollTimer) window.clearInterval(importPollTimer); importPollTimer = undefined }
async function refreshImports() { if (!importTarget.value) return; try { imports.value = await api.get(`/k8s/persistent-volume-claims/${importTarget.value.name}/imports?environment_id=${environmentID.value}`) || []; syncImportPolling() } catch (e) { error.value = e.message || '读取目录导入记录失败'; stopImportPolling() } }
async function openImport(claim) { importTarget.value = claim; importForm.value = { source_server_id: backupServers.value[0]?.id || 0, source_path: '', confirm_data_replace: false }; await refreshImports() }
async function createImport() { if (!importTarget.value) return; saving.value = true; error.value = ''; try { await api.post(`/k8s/persistent-volume-claims/${importTarget.value.name}/imports`, { environment_id: environmentID.value, ...importForm.value }); await refreshImports() } catch (e) { error.value = e.message || '创建目录导入失败' } finally { saving.value = false } }
async function deleteImportBackup(task) { if (!importTarget.value || !window.confirm('删除后无法通过平台恢复本次导入前的数据，确定删除本地归档吗？')) return; saving.value = true; error.value = ''; try { await api.delete(`/k8s/persistent-volume-claims/${importTarget.value.name}/imports/${task.id}/backup`, { environment_id: environmentID.value }); await refreshImports() } catch (e) { error.value = e.message || '删除导入备份失败' } finally { saving.value = false } }
async function deleteClaim() { if (!deleteTarget.value) return; saving.value = true; error.value = ''; try { await api.delete(`/k8s/persistent-volume-claims/${deleteTarget.value.name}`, { environment_id: environmentID.value, confirm_data_delete: true }); deleteTarget.value = null; await loadClaims() } catch (e) { error.value = e.message || '删除存储卷失败' } finally { saving.value = false } }

watch(projectID, () => { const environments = selectedProject.value?.environments || []; if (!environments.some(item => item.id === environmentID.value)) environmentID.value = environments.length === 1 ? environments[0].id : 0 })
watch(environmentID, loadClaims)
watch(backupTarget, target => { if (!target) stopBackupPolling() })
watch(importTarget, target => { if (!target) stopImportPolling() })
onUnmounted(() => { stopMigrationPolling(); stopBackupPolling(); stopImportPolling() })
loadProjects()
</script>

